package io.github.ningpp.compat;

/** Replacement for System.NotFiniteNumberException (generated by CSharpToJava converter). */
public class NotFiniteNumberException extends ArithmeticException {
    private int hresult;
    public NotFiniteNumberException() { super(); }
    public NotFiniteNumberException(String message) { super(message); }

    public int getHResult() { return hresult; }
    public void setHResult(int value) { this.hresult = value; }
}
